</style></head><body><main class="wrap"><section class="card"><div class="top"><div><div class="eyebrow">Secure payment</div><div class="title">Invoice #<?= (int) $session->invoice_id ?></div></div><div class="amount"><?= htmlspecialchars(number_format((float)$data['amount'],2),ENT_QUOTES,'UTF-8') ?> <span class="currency"><?= htmlspecialchars($data['currency'],ENT_QUOTES,'UTF-8') ?></span></div></div><?php if ($enableRevolutPay || $enableWallets): ?><div id="methods" class="methods"><h2 class="methods-title">Choose a payment method</h2><div id="revolut-pay-option" class="method"><div class="method-label">Revolut Pay</div><div id="revolut-pay" class="sdk-target"></div></div><div id="wallet-option" class="method"><div class="method-label">Apple Pay or Google Pay</div><div id="wallet" class="sdk-target"></div></div><div class="divider">Credit or debit card</div></div><?php endif; ?><label class="label" for="field">Card details</label><div id="field"></div><div id="error" class="error" role="alert" aria-live="polite"></div><button id="pay" type="button" disabled><span class="spinner"></span><span id="button-text">Pay <?= htmlspecialchars($data['currency'].' '.number_format((float)$data['amount'],2),ENT_QUOTES,'UTF-8') ?></span></button><a id="cancel" class="cancel" href="<?= htmlspecialchars($returnUrl, ENT_QUOTES, 'UTF-8') ?>" target="_top">Cancel and return to invoice</a><p class="help">Your payment details are securely processed by Revolut and never pass through WHMCS.</p><footer class="provider"><span class="provider-label">Powered by</span><img class="provider-logo" src="revolut-business-logo.png" alt="Revolut Business"><div>Copyright &copy; <?= date('Y') ?> Revolut Limited<br>View our <a href="https://www.revolut.com/legal/privacy" target="_blank" rel="noopener noreferrer">privacy policy</a></div></footer></section></main>
<script src="<?= $sdk ?>"></script><script>
(function(){'use strict';const pay=document.getElementById('pay'),cancel=document.getElementById('cancel'),err=document.getElementById('error'),txt=document.getElementById('button-text'),target=document.getElementById('field');let busy=false,valid=false,field;
function applyWhmcsTheme(){try{if(window.parent===window)return;const source=window.parent.document.querySelector('.btn-primary');if(!source)return;const style=window.parent.getComputedStyle(source),color=style.backgroundColor;if(!color||color==='rgba(0, 0, 0, 0)')return;document.documentElement.style.setProperty('--primary',color);document.documentElement.style.setProperty('--primary-hover',color);const match=color.match(/[\d.]+/g);if(match&&match.length>=3)document.documentElement.style.setProperty('--primary-ring','rgba('+match[0]+','+match[1]+','+match[2]+',.18)')}catch(e){}}
function message(text){err.textContent=text||'';err.classList.toggle('show',!!text)}
function errorDetail(e){return String((e&&e.message)||(e&&e.code)||(e&&e.type)||e||'Unknown SDK error').slice(0,500)}
function report(stage,e){try{fetch(<?= json_encode($clientLogUrl) ?>,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({session:<?= json_encode($token) ?>,stage:stage,message:errorDetail(e)}),credentials:'same-origin',keepalive:true})}catch(ignore){}}
function setBusy(on){busy=on;document.body.classList.toggle('checkout-busy',on);pay.disabled=on||!valid;pay.classList.toggle('processing',on);cancel.classList.toggle('disabled',on);cancel.setAttribute('aria-disabled',on?'true':'false');txt.textContent=on?'Processing payment…':<?= json_encode('Pay '.$data['currency'].' '.number_format((float)$data['amount'],2)) ?>}
function customerMessage(e){const code=String((e&&e.type)||(e&&e.name)||'');if(code.indexOf('declin')>=0)return 'Your card was declined. Please try another card or contact your bank.';if(code.indexOf('cancel')>=0)return 'Payment was cancelled. You can try again when ready.';return (e&&e.message&&String(e.message).length<180)?e.message:'We could not complete the payment. Please check your details and try again.'}
function finish(){setBusy(true);txt.textContent='Payment received — returning…';window.location.replace(<?= json_encode($complete) ?>)}
applyWhmcsTheme();
<?php if ($initialStatus === 'failed'): ?>message('The wallet payment could not be completed. Please try again or choose another payment method.');<?php elseif ($initialStatus === 'cancelled'): ?>message('Payment was cancelled. You can try again when ready.');<?php endif; ?>
if(typeof RevolutCheckout!=='function'){message('The secure payment form could not load. Please refresh the page.');return}
RevolutCheckout(<?= json_encode($data['orderToken']) ?>,<?= json_encode($environment) ?>).then(function(instance){field=instance.createCardField({target:target,theme:'light',showLoadingIndicator:true,savePaymentMethodFor:'merchant',name:<?= json_encode($data['name']) ?>,email:<?= json_encode($data['email']) ?>,phone:<?= json_encode($data['phone']) ?>,billingAddress:<?= json_encode($data['billingAddress']) ?>,styles:{default:{fontSize:'16px',color:'#17212b',fontFamily:'system-ui, sans-serif'},focused:{color:'#101828'},invalid:{color:'#b42318'}},classes:{default:'field-default',focused:'field-focused',invalid:'field-invalid',completed:'field-completed'},onStatusChange:function(s){valid=!!s.completed&&!s.invalid;pay.disabled=busy||!valid},onValidation:function(errors){if(errors&&errors.length){message(errors[0].message||'Please check your card details.')}else{message('')}},onSuccess:finish,onCancel:function(){setBusy(false);message('Payment was cancelled. You can try again when ready.')},onError:function(e){setBusy(false);message(customerMessage(e))}});pay.addEventListener('click',function(){if(busy||!valid)return;message('');setBusy(true);try{field.submit()}catch(e){setBusy(false);message(customerMessage(e))}})}).catch(function(){message('The secure card form could not be started. Please refresh the page or use another payment method.')});
<?php if ($enableRevolutPay || $enableWallets): ?>
if(typeof RevolutCheckout.payments==='function')Promise.resolve().then(function(){return RevolutCheckout.payments({publicToken:<?= json_encode($publicKey) ?>,mode:<?= json_encode($environment) ?>,locale:'auto'})}).then(function(methods){
const createOrder=function(){return Promise.resolve({publicId:<?= json_encode($data['orderToken']) ?>})};
<?php if ($enableRevolutPay): ?>const revolutOption=document.getElementById('revolut-pay-option');document.getElementById('methods').classList.add('show');revolutOption.classList.add('show');methods.revolutPay.mount('#revolut-pay',{currency:<?= json_encode($data['currency']) ?>,totalAmount:<?= (int) $minorAmount ?>,createOrder:createOrder,customer:{name:<?= json_encode($data['name']) ?>,email:<?= json_encode($data['email']) ?>,phone:<?= json_encode($data['phone']) ?>,billingAddress:<?= json_encode($data['billingAddress']) ?>},savePaymentMethodForMerchant:true,buttonStyle:{size:'large',radius:'large',variant:'dark',height:'48px'},mobileRedirectUrls:{success:<?= json_encode($complete) ?>,failure:<?= json_encode($redirectBase . '&status=failed') ?>,cancel:<?= json_encode($redirectBase . '&status=cancelled') ?>}});methods.revolutPay.on('click',function(){message('');setBusy(true)});methods.revolutPay.on('payment',function(event){if(event.type==='success')finish();else if(event.type==='cancel'){setBusy(false);message('Payment was cancelled. You can try again when ready.')}else if(event.type==='error'){setBusy(false);message(customerMessage(event.error))}});<?php endif; ?>
<?php if ($enableWallets): ?>const walletOption=document.getElementById('wallet-option');const hideWallet=function(e){walletOption.classList.remove('show');try{wallet.destroy()}catch(ignore){}if(e)report('wallet_unavailable',e)};const wallet=methods.paymentRequest(document.getElementById('wallet'),{amount:<?= (int) $minorAmount ?>,currency:<?= json_encode($data['currency']) ?>,createOrder:createOrder,buttonStyle:{action:'pay',size:'large',radius:'large',variant:'dark',height:'48px'},onSuccess:finish,onCancel:function(){setBusy(false);message('Payment was cancelled. You can try again when ready.')},onError:function(e){setBusy(false);hideWallet(e)}});wallet.canMakePayment().then(function(method){if(!method){hideWallet();return}document.getElementById('methods').classList.add('show');walletOption.classList.add('show');return Promise.resolve(wallet.render()).catch(hideWallet)}).catch(hideWallet);<?php endif; ?>
}).catch(function(e){report('payments_initialise',e);<?php if ($enableRevolutPay): ?>document.getElementById('revolut-pay-option').classList.remove('show');<?php endif; ?>document.getElementById('methods').classList.remove('show');message('Revolut Pay and wallets could not load. You can continue securely by card.')});
else{report('payments_unavailable','RevolutCheckout.payments is not available');message('Revolut Pay and wallets could not load. You can continue securely by card.')}
<?php endif; ?>
